int minimumTourLength(int N, int[] X) {
    int minTourLength = Integer.MAX_VALUE;

    for (int i = 1; i < N; i++) {
        int tourLength = 0;

        for (int j = 0; j < X.length - 1; j++) {
            if ((X[j] == i && X[j + 1] == i + 1) || (X[j] == i + 1 && X[j + 1] == i)) {
                continue; // Simulate closing the bridge between island i and i+1
            }
            tourLength += Math.abs(X[j + 1] - X[j]);
        }

        minTourLength = Math.min(minTourLength, tourLength);
    }

    return minTourLength;
}
